window.SUBJECTS['finance'].mcqs.push(...[{"u":"Unit I","t":"Finance Function","n":2001,"q":"The finance function mainly deals with","o":["hiring and training staff","advertising the products","selling goods to customers","raising funds and using them effectively"],"a":3,"e":"Finance means procurement and effective use of funds.","w":["Hiring and training is the HR function.","Advertising is part of marketing.","Selling is the marketing function.",""],"g":1},{"u":"Unit I","t":"Finance Function","n":2002,"q":"Which of the following is NOT one of the three core financial decisions?","o":["Production decision","Dividend decision","Financing decision","Investment decision"],"a":0,"e":"Production is an operations decision, not a financial one.","w":["","Dividend is a core decision.","Financing is a core decision.","Investment is a core decision."],"g":1},{"u":"Unit I","t":"Finance Function","n":2003,"q":"Checking whether funds are used efficiently through budgets and variance analysis is","o":["financial control","financial planning","profit planning","liquidity management"],"a":0,"e":"Control compares actual use of funds with the budget.","w":["","Planning estimates future fund needs.","Profit planning studies cost-volume-profit.","Liquidity management keeps cash for short-term dues."],"g":1},{"u":"Unit I","t":"Objectives","n":2004,"q":"Profit maximisation is criticised mainly because it","o":["looks only at the long term","is measured by the share price","ignores time value of money and risk","gives too much weight to risk"],"a":2,"e":"Profit does not adjust for timing of earnings or risk.","w":["Profit maximisation is short-term oriented.","Share price belongs to wealth maximisation.","","It ignores risk; it does not overweight it."],"g":1},{"u":"Unit I","t":"Objectives","n":2005,"q":"Shareholder wealth is measured by","o":["the book value of assets","the total sales of the firm","the accounting profit for the year","the market price of the equity shares"],"a":3,"e":"Wealth = number of shares x market price per share.","w":["Book value ignores market perception.","Sales do not show wealth.","Accounting profit is the profit-maximisation yardstick.",""],"g":1},{"u":"Unit I","t":"Objectives","n":2006,"q":"Which statement about wealth maximisation is correct?","o":["It ignores time value of money","It is short-term and ignores risk","It is long-term and considers risk","It is vague like profit"],"a":2,"e":"Wealth maximisation discounts risky cash flows over the long term.","w":["Wealth maximisation uses discounted cash flows.","That describes profit maximisation.","","The market price is precise and observable."],"g":1},{"u":"Unit I","t":"Decisions","n":2007,"q":"The decision about the right mix of debt and equity is the","o":["liquidity decision","investment decision","financing decision","dividend decision"],"a":2,"e":"The capital structure mix is the financing decision.","w":["Liquidity is a working capital matter.","Investment decides where to put funds.","","Dividend decides payout versus retention."],"g":1},{"u":"Unit I","t":"Decisions","n":2008,"q":"Deciding how much profit to distribute and how much to retain is the","o":["dividend decision","control decision","financing decision","investment decision"],"a":0,"e":"That is exactly the dividend decision.","w":["","Control is not a core decision.","Financing is about raising funds.","Investment is about asset selection."],"g":1},{"u":"Unit I","t":"Decisions","n":2009,"q":"The long-term part of the investment decision is called","o":["working capital management","capital budgeting","capital structure","dividend policy"],"a":1,"e":"Long-term asset decisions are capital budgeting.","w":["Working capital is the short-term part.","","Capital structure is a financing matter.","Dividend policy is a payout matter."],"g":1},{"u":"Unit I","t":"Time Value of Money","n":2010,"q":"A rupee today is worth more than a rupee tomorrow mainly because","o":["prices never change","rupee notes get old","it can be invested to earn a return","banks refuse future money"],"a":2,"e":"Money in hand can earn interest; also inflation and risk apply.","w":["Prices do change - inflation is another reason.","Notes losing age is not the reason.","","Banks accept future money."],"g":1},{"u":"Unit I","t":"Time Value of Money","n":2011,"q":"The future value of Rs 10,000 at 8% compound interest for 5 years is about","o":["Rs 13,605","Rs 14,693","Rs 14,000","Rs 15,000"],"a":1,"e":"FV = 10,000 x (1.08)^5 = 14,693.","w":["13,605 is the PV-style discounting, not compounding.","","14,000 is simple interest (8% x 5 years).","15,000 is a rounded guess."],"g":1},{"u":"Unit I","t":"Time Value of Money","n":2012,"q":"The present value of Rs 50,000 receivable after 3 years at 10% is about","o":["Rs 65,050","Rs 35,000","Rs 37,566","Rs 45,455"],"a":2,"e":"PV = 50,000 / (1.10)^3 = 37,566.","w":["65,050 is the future value, not the present value.","35,000 uses simple deduction of 10% x 3.","","45,455 is the PV for one year only."],"g":1},{"u":"Unit I","t":"Time Value of Money","n":2013,"q":"Using the rule of 72, money doubles at 9% in about","o":["8 years","12 years","6 years","9 years"],"a":0,"e":"72 / 9 = 8 years.","w":["","12 years would be about 6% interest.","6 years would need 12%.","9 years does not use the rule."],"g":1},{"u":"Unit I","t":"PV and Discount Rate","n":2014,"q":"When the discount rate increases, the present value of a future sum","o":["becomes zero","stays the same","increases","decreases"],"a":3,"e":"PV and discount rate move in opposite directions.","w":["PV becomes small, not zero.","PV changes with the rate.","A higher rate lowers PV.",""],"g":1},{"u":"Unit I","t":"PV and Discount Rate","n":2015,"q":"The present value of Rs 1,000 due after 5 years is highest at a discount rate of","o":["all are equal","15%","10%","5%"],"a":3,"e":"At 5% PV = 783.53, at 10% = 620.92, at 15% = 497.18.","w":["The rate clearly changes the PV.","15% gives the lowest PV.","10% gives a lower PV than 5%.",""],"g":1},{"u":"Unit I","t":"PV and Discount Rate","n":2016,"q":"Present value is also inversely related to","o":["the number of years","the future sum","the compounding factor of FV only","the face value of the bond"],"a":0,"e":"The more distant the cash flow, the lower its present value.","w":["","PV rises with the future sum.","That is not an independent link.","Face value is a bond term."],"g":1},{"u":"Unit I","t":"Annuity","n":2017,"q":"An annuity whose payments are made at the beginning of each period is","o":["an annuity due","an ordinary annuity","a perpetuity","a sinking fund"],"a":0,"e":"Payments at the start of each period make an annuity due.","w":["","Ordinary annuity pays at the end.","A perpetuity never ends.","A sinking fund is a repayment fund."],"g":1},{"u":"Unit I","t":"Annuity","n":2018,"q":"Rs 5,000 deposited at the end of each year for 5 years at 10% grows to about","o":["Rs 25,000","Rs 8,053","Rs 33,578","Rs 30,526"],"a":3,"e":"FVA = 5,000 x 6.1051 = 30,525.5.","w":["25,000 is the total deposited with no interest.","8,053 is the FV of one single deposit.","33,578 is the annuity-due value.",""],"g":1},{"u":"Unit I","t":"Annuity","n":2019,"q":"If payments in an ordinary annuity are made at the start of each year instead, the present value","o":["doubles","remains unchanged","increases by a factor of (1 + r)","decreases by a factor of (1 + r)"],"a":2,"e":"Each payment is one period earlier, so PV is multiplied by (1 + r).","w":["It rises by (1 + r), not double.","Timing changes the value.","","Earlier payments are worth more, not less."],"g":1},{"u":"Unit I","t":"Annuity","n":2020,"q":"The present value of Rs 10,000 received at the end of each year for 4 years at 12% is about","o":["Rs 34,018","Rs 30,373","Rs 40,000","Rs 15,735"],"a":1,"e":"PVA = 10,000 x 3.0373 = 30,373.","w":["34,018 is the annuity-due value.","","40,000 is the undiscounted total.","15,735 is the FV factor result for one payment."],"g":1},{"u":"Unit I","t":"Annuity","n":2021,"q":"A perpetuity of Rs 5,000 a year at 10% has a present value of","o":["Rs 5,000","Rs 500","Rs 50,000","Rs 1,00,000"],"a":2,"e":"PV = A / r = 5,000 / 0.10 = 50,000.","w":["5,000 is only one year's payment.","500 divides the wrong way round.","","1,00,000 uses 5% instead of 10%."],"g":1},{"u":"Unit I","t":"Bonds","n":2022,"q":"A bond is valued as","o":["the present value of its interest and face value","its face value paid back at maturity only","the total of the interest paid over its whole life","the price at which it was first issued"],"a":0,"e":"Bond value = PV of coupons + PV of maturity value.","w":["","Face value alone ignores the interest.","Total interest is undiscounted.","Issue price is history, not value."],"g":1},{"u":"Unit I","t":"Bonds","n":2023,"q":"A bond sells at a premium when the","o":["coupon rate is above the market rate","coupon rate is below the market rate","bond has no maturity","coupon rate equals the market rate"],"a":0,"e":"A higher coupon makes the bond attractive, so price exceeds face value.","w":["","That gives a discount.","Maturity does not decide premium.","That gives par."],"g":1},{"u":"Unit I","t":"Bonds","n":2024,"q":"A Rs 1,000 bond with a 10% coupon and 5 years to maturity is priced when the required return is 12% at about","o":["Rs 928","Rs 1,080","Rs 1,200","Rs 1,000"],"a":0,"e":"V = 100 x 3.6048 + 1,000 x 0.5674 = about 928 (a discount).","w":["","1,080 is the value at 8%.","1,200 has no basis.","1,000 is the value at 10%."],"g":1},{"u":"Unit I","t":"Bonds","n":2025,"q":"When market interest rates rise, the price of an existing fixed-coupon bond","o":["does not change","falls","rises","doubles"],"a":1,"e":"Bond price and interest rate move in opposite directions.","w":["Price responds to rates.","","Rising rates make old bonds less attractive.","Price does not double."],"g":1},{"u":"Unit II","t":"Capital Budgeting","n":2026,"q":"Capital budgeting decisions are important because they","o":["can be reversed at any time without any cost","involve large sums for a long period and are hard to reverse","involve small expenses that are met every day","are routine decisions taken almost every day"],"a":1,"e":"Capital decisions commit large funds for long and are costly to reverse.","w":["Reversal is difficult and costly.","","Small daily expenses are revenue items.","Capital decisions are occasional."],"g":1},{"u":"Unit II","t":"Capital Budgeting","n":2027,"q":"Replacing worn-out machinery is called a","o":["diversification decision","expansion decision","mandatory decision","replacement decision"],"a":3,"e":"Replacing old assets is a replacement proposal.","w":["Diversification enters new products.","Expansion increases capacity.","Mandatory is required by law.",""],"g":1},{"u":"Unit II","t":"Capital Budgeting","n":2028,"q":"Which is the correct order of the capital budgeting process?","o":["Implement, select, screen, review, identify, estimate","Identify, screen, estimate cash flows, select, implement, review","Select, identify, review, estimate, implement, screen","Review, implement, select, estimate, screen, identify"],"a":1,"e":"The process starts with proposals and ends with a post-completion review.","w":["Implementation comes after selection.","","Selection cannot precede identification.","That is the reverse order."],"g":1},{"u":"Unit II","t":"Capital Budgeting","n":2029,"q":"Cash flow after tax (CFAT) equals","o":["profit after tax plus depreciation","profit after tax minus depreciation","profit before tax plus interest","sales minus tax"],"a":0,"e":"Depreciation is a non-cash expense, so it is added back.","w":["","Subtracting depreciation understates cash.","That is an EBIT-type figure.","Sales minus tax ignores costs."],"g":1},{"u":"Unit II","t":"Payback Period","n":2030,"q":"A project costing Rs 5,00,000 gives Rs 1,25,000 a year. Its payback period is","o":["4 years","5 years","3 years","2.5 years"],"a":0,"e":"5,00,000 / 1,25,000 = 4 years.","w":["","5 years divides by the wrong number.","3 years overstates the inflow.","2.5 years has no basis."],"g":1},{"u":"Unit II","t":"Payback Period","n":2031,"q":"The main weakness of the payback method is that it","o":["is too complicated to compute","ignores time value of money and later cash flows","uses discounted cash flows","measures profitability very exactly"],"a":1,"e":"Payback ignores timing and anything after recovery.","w":["It is a simple method.","","Plain payback does not discount.","It does not measure profitability."],"g":1},{"u":"Unit II","t":"Payback Period","n":2032,"q":"Investment Rs 4,00,000; inflows of Rs 1,00,000, 1,50,000, 2,00,000 and 2,50,000. The payback period is","o":["2.75 years","2 years","2.5 years","3 years"],"a":0,"e":"After 2 years 2,50,000 is recovered; 1,50,000 / 2,00,000 = 0.75, so 2.75 years.","w":["","2 years leaves part unrecovered.","2.5 years uses the wrong balance.","3 years rounds up."],"g":1},{"u":"Unit II","t":"NPV","n":2033,"q":"A project should be accepted under the NPV method when","o":["IRR is below the cost of capital","payback is longest","NPV is less than zero","NPV is greater than zero"],"a":3,"e":"Positive NPV adds to shareholder wealth.","w":["IRR below the cost of capital means reject.","A long payback is not the rule.","Negative NPV destroys wealth.",""],"g":1},{"u":"Unit II","t":"NPV","n":2034,"q":"Investment Rs 1,00,000; inflows Rs 40,000, 50,000, 60,000 over 3 years; cost of capital 10%. The NPV is about","o":["Rs 1,22,765","Rs 50,000","Rs 22,765","Rs -22,765"],"a":2,"e":"PV of inflows is 1,22,765; minus 1,00,000 gives 22,765.","w":["1,22,765 is the PV of inflows, not the NPV.","50,000 is the undiscounted surplus.","","A negative sign is wrong because inflows exceed the cost."],"g":1},{"u":"Unit II","t":"NPV","n":2035,"q":"NPV is considered the best capital budgeting method mainly because it","o":["is easy to calculate by eye","ignores time value of money","measures the addition to shareholder wealth","does not need any discount rate"],"a":2,"e":"NPV links directly to wealth maximisation.","w":["It needs a discount rate and calculation.","NPV discounts cash flows.","","The discount rate is an input."],"g":1},{"u":"Unit II","t":"Profitability Index","n":2036,"q":"The profitability index is","o":["NPV divided by years","PV of cash inflows divided by initial investment","initial investment divided by PV of inflows","profit divided by sales"],"a":1,"e":"PI = PV of inflows / initial investment.","w":["Years play no part.","","That is the inverse ratio.","That is a profit margin."],"g":1},{"u":"Unit II","t":"Profitability Index","n":2037,"q":"A project with a profitability index of 1.23 should be","o":["accepted","accepted only if NPV is negative","ignored","rejected"],"a":0,"e":"PI above 1 means NPV is positive, so accept.","w":["","PI above 1 already means positive NPV.","A PI of 1.23 is a clear signal.","Rejection is for PI below 1."],"g":1},{"u":"Unit II","t":"Profitability Index","n":2038,"q":"The profitability index is especially useful when","o":["cash flows are unknown","funds are limited (capital rationing)","the discount rate is zero","there is only one project"],"a":1,"e":"PI ranks projects by value per rupee invested.","w":["Cash flows must be estimated.","","A zero rate makes discounting pointless.","With one project the NPV rule is enough."],"g":1},{"u":"Unit II","t":"IRR","n":2039,"q":"The IRR is the rate at which","o":["the profit is highest","the payback is the shortest","the cost of capital is lowest","the NPV of the project is zero"],"a":3,"e":"IRR makes PV of inflows equal to the investment.","w":["IRR is not about the highest profit.","Payback is a separate measure.","IRR is not the cost of capital.",""],"g":1},{"u":"Unit II","t":"IRR","n":2040,"q":"A project is accepted under the IRR method if","o":["IRR is less than the cost of capital","IRR is equal to the payback","IRR is exactly zero","IRR is more than the cost of capital"],"a":3,"e":"Earning more than the cost of funds adds value.","w":["Lower IRR means reject.","IRR and payback are different things.","Zero IRR means no return.",""],"g":1},{"u":"Unit II","t":"IRR","n":2041,"q":"If NPV is +2,778 at 20% and -578 at 22%, the IRR by interpolation is about","o":["21.0%","22.5%","21.7%","20.5%"],"a":2,"e":"20 + [2,778 / (2,778 + 578)] x 2 = 21.66%.","w":["21.0% is not what interpolation gives.","22.5% lies beyond 22%.","","20.5% is too close to 20%."],"g":1},{"u":"Unit II","t":"IRR","n":2042,"q":"For mutually exclusive projects, when NPV and IRR conflict, the better method is generally","o":["NPV","IRR","profitability index only","payback"],"a":0,"e":"NPV measures wealth creation directly.","w":["","IRR can mislead on scale and timing.","PI can also conflict on size.","Payback ignores value."],"g":1},{"u":"Unit III","t":"Capital Structure","n":2043,"q":"Capital structure refers to the","o":["number of employees","level of annual sales","mix of long-term sources of funds","list of current assets"],"a":2,"e":"It is the proportion of debt, preference, equity and retained earnings.","w":["Employee numbers are an HR matter.","Sales are not a source of funds.","","Current assets are a working capital matter."],"g":1},{"u":"Unit III","t":"Capital Structure","n":2044,"q":"The optimum capital structure is the one that","o":["uses only equity and no borrowed funds","minimises the overall cost of capital and maximises firm value","uses only debt and no owners' funds","maximises the interest paid to lenders"],"a":1,"e":"Lowest cost of capital and highest value define the optimum.","w":["All-equity may cost more than a mix.","","All-debt is too risky.","More interest is not a goal."],"g":1},{"u":"Unit III","t":"Capital Structure","n":2045,"q":"Raising funds by debt rather than new equity helps a promoter mainly to","o":["avoid paying any return","keep control of the company","increase the number of shareholders","reduce the tax rate"],"a":1,"e":"Debt does not dilute ownership.","w":["Debt carries compulsory interest.","","New equity increases shareholders.","Debt does not change the tax rate."],"g":1},{"u":"Unit III","t":"Capital Structure","n":2046,"q":"A firm with stable and predictable earnings can usually","o":["only use retained earnings","afford no debt at all","afford a higher proportion of debt","only issue preference shares"],"a":2,"e":"Stable cash flows can service fixed interest comfortably.","w":["Retained earnings may not be enough.","Stable earnings support borrowing.","","Preference shares are not the only option."],"g":1},{"u":"Unit III","t":"Leverage","n":2048,"q":"Financial leverage measures the sensitivity of","o":["EPS to a change in sales","sales to a change in price","EPS to a change in EBIT","EBIT to a change in sales"],"a":2,"e":"DFL = % change in EPS / % change in EBIT.","w":["That is combined leverage.","Price effect is not leverage.","","That is operating leverage."],"g":1},{"u":"Unit III","t":"Leverage","n":2049,"q":"Combined leverage is equal to","o":["operating leverage divided by financial leverage","operating leverage multiplied by financial leverage","operating leverage plus financial leverage","financial leverage minus operating leverage"],"a":1,"e":"DCL = DOL x DFL.","w":["Division has no meaning here.","","They are multiplied, not added.","Subtraction has no meaning here."],"g":1},{"u":"Unit III","t":"Leverage","n":2050,"q":"Sales Rs 1,00,000; variable cost Rs 40,000; fixed cost Rs 20,000. The degree of operating leverage is","o":["0.67","1.5","3.0","2.0"],"a":1,"e":"Contribution 60,000 / EBIT 40,000 = 1.5.","w":["0.67 inverts the ratio.","","3.0 has no basis.","2.0 is the combined leverage with interest of 10,000."],"g":1},{"u":"Unit III","t":"Leverage","n":2051,"q":"EBIT Rs 40,000 and interest Rs 10,000. The degree of financial leverage is","o":["4.0","0.75","1.5","1.33"],"a":3,"e":"EBIT / EBT = 40,000 / 30,000 = 1.33.","w":["4.0 divides EBIT by interest.","0.75 inverts the ratio.","1.5 is the operating leverage here.",""],"g":1},{"u":"Unit III","t":"Leverage","n":2052,"q":"A firm has DOL of 1.5 and DFL of 1.33. A 10% fall in sales will reduce EPS by about","o":["10%","13%","15%","20%"],"a":3,"e":"DCL = 1.5 x 1.33 = 2, so EPS falls 2 x 10% = 20%.","w":["10% ignores leverage.","13% is the fall due to DFL on a 10% EBIT fall.","15% is the fall in EBIT only.",""],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2053,"q":"Interest on debt is tax-deductible, so the cost of debt after tax is","o":["equal to the interest rate","higher than the interest rate","zero","lower than the interest rate"],"a":3,"e":"After-tax cost = interest rate x (1 - tax rate).","w":["Tax makes it lower, not equal.","The tax shield reduces the cost.","Debt still has a cost.",""],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2054,"q":"A company pays 12% interest and the tax rate is 30%. The after-tax cost of debt is","o":["8.4%","12%","9.6%","3.6%"],"a":0,"e":"12 x (1 - 0.30) = 8.4%.","w":["","12% ignores the tax shield.","9.6% takes 20% off.","3.6% is the tax saving, not the cost."],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2055,"q":"Preference dividend has no tax benefit because it is paid","o":["by the government","out of profit after tax","out of profit before tax","only to debenture holders"],"a":1,"e":"Dividends are an appropriation of after-tax profit.","w":["Companies pay it, not the government.","","Interest, not dividend, is paid before tax.","Debenture holders get interest."],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2056,"q":"Which source of capital is generally the costliest?","o":["Preference share capital","Equity share capital","Debt","Government grant"],"a":1,"e":"Equity holders bear the most risk and get no tax saving.","w":["Preference is cheaper than equity.","","Debt is the cheapest because of the tax shield.","Grant is not a standard source here."],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2057,"q":"With D1 = Rs 4, market price Rs 50 and growth 5%, the cost of equity is","o":["9%","13%","5%","8%"],"a":1,"e":"Ke = 4/50 + 5% = 8% + 5% = 13%.","w":["9% adds the wrong figures.","","5% is the growth rate only.","8% is the dividend yield only."],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2058,"q":"Capital of Rs 5,00,000 debt (7% after tax), Rs 2,00,000 preference (12%) and Rs 3,00,000 equity (16%) gives a WACC of","o":["10.7%","11.7%","9.0%","12.0%"],"a":0,"e":"(35,000 + 24,000 + 48,000) / 10,00,000 = 10.7%.","w":["","11.7% adds an error.","9.0% is not the weighted figure.","12.0% is the simple average of the three rates."],"g":1},{"u":"Unit III","t":"Cost of Capital","n":2059,"q":"WACC is used in capital budgeting as the","o":["payback period","discount rate for NPV","tax rate","depreciation rate"],"a":1,"e":"Projects must earn more than the WACC.","w":["Payback is measured in years.","","Tax rate is set by law.","Depreciation rate is an accounting rule."],"g":1},{"u":"Unit IV","t":"Dividend Decision","n":2060,"q":"Dividend is paid out of the company's","o":["bank loans only","profit before tax","sales revenue","profit after tax"],"a":3,"e":"Dividends are distributed from after-tax profit.","w":["Loans are not the proper source.","Tax is paid first.","Revenue includes costs.",""],"g":1},{"u":"Unit IV","t":"Dividend Decision","n":2061,"q":"A firm that retains more profit is relying more on","o":["bank overdraft","debentures","trade credit","internal financing"],"a":3,"e":"Retained earnings are an internal source of finance.","w":["Overdraft is external.","Debentures are external debt.","Trade credit is a working capital source.",""],"g":1},{"u":"Unit IV","t":"Dividend Policy","n":2062,"q":"A steady or rising dividend usually signals","o":["that the business is making a loss","that the firm has a weak cash position","that the firm plans to close down soon","financial health and management confidence"],"a":3,"e":"Stable dividends tell the market the firm is doing well.","w":["Losses would reduce dividends.","Weak cash cannot support steady dividends.","A closing firm would stop dividends.",""],"g":1},{"u":"Unit IV","t":"Dividend Policy","n":2063,"q":"Retired investors who want regular income prefer a firm with","o":["no dividend and high growth","a high stable dividend","very volatile earnings","only bonus shares"],"a":1,"e":"Regular dividend income suits retirees.","w":["That suits growth investors.","","Volatile earnings give uncertain income.","Bonus shares give no cash."],"g":1},{"u":"Unit IV","t":"Dividend Factors","n":2064,"q":"Even a profitable firm may be unable to pay a dividend because of poor","o":["profitability","liquidity (cash position)","brand image","number of products"],"a":1,"e":"Profit is not cash; dividends need actual cash.","w":["The firm is already profitable.","","Brand image does not stop payment.","Product count is irrelevant."],"g":1},{"u":"Unit IV","t":"Dividend Factors","n":2065,"q":"A firm with many profitable investment opportunities will usually","o":["borrow to pay dividends","retain more and pay a lower dividend","stop all investment","pay a higher dividend"],"a":1,"e":"Retained earnings fund the profitable projects cheaply.","w":["Borrowing to pay dividends is wasteful.","","Profitable projects should be taken.","Higher dividends would leave less for projects."],"g":1},{"u":"Unit IV","t":"Dividend Factors","n":2066,"q":"Loan agreements that limit the dividend a company can pay are an example of","o":["shareholder preference","inflation effects","contractual restrictions","tax considerations"],"a":2,"e":"Lenders may set contractual limits on payout.","w":["Shareholder preference is a market factor.","Inflation is an economic condition.","","Tax is about tax treatment."],"g":1},{"u":"Unit IV","t":"Dividend Policy Types","n":2067,"q":"Paying a fixed percentage of profit as dividend every year is the","o":["constant payout ratio policy","residual dividend policy","stable dividend policy","regular plus extra policy"],"a":0,"e":"The dividend then moves up and down with profit.","w":["","Residual pays what is left after investment.","Stable policy pays a fixed amount.","Regular plus extra adds a bonus in good years."],"g":1},{"u":"Unit IV","t":"Dividend Policy Types","n":2068,"q":"Paying dividends only from what is left after all profitable investments are financed is the","o":["constant payout policy","stable dividend policy","residual dividend policy","stock dividend"],"a":2,"e":"Dividends are the residual earnings.","w":["Constant payout fixes the ratio.","Stable policy fixes the amount.","","A stock dividend is a bonus issue."],"g":1},{"u":"Unit IV","t":"Walter's Model","n":2069,"q":"In Walter's model a growth firm is one where","o":["k is zero","r is less than k","r is greater than k","r equals k"],"a":2,"e":"The firm earns more on reinvestment than shareholders could elsewhere.","w":["k is never zero.","That is a declining firm.","","That is a normal firm."],"g":1},{"u":"Unit IV","t":"Walter's Model","n":2070,"q":"According to Walter, a growth firm should","o":["retain all earnings","pay a 50% dividend","issue new debt only","pay out all earnings"],"a":0,"e":"With r above k, retention raises share value.","w":["","Value is not maximised at 50%.","Debt is outside the model.","Paying out all earnings suits a declining firm."],"g":1},{"u":"Unit IV","t":"Walter's Model","n":2071,"q":"In Walter's model, a normal firm (r = k) has a share value that is","o":["the same for every dividend payout","highest when everything is paid out","highest when nothing is paid out","always equal to zero"],"a":0,"e":"When r = k, dividend policy does not matter.","w":["","That fits a declining firm.","That fits a growth firm.","Value cannot be zero."],"g":1},{"u":"Unit IV","t":"Walter's Model","n":2072,"q":"With E = Rs 8, k = 10%, r = 15% and D = 0, Walter's share price is","o":["Rs 100","Rs 80","Rs 120","Rs 64"],"a":2,"e":"P = [0 + (0.15/0.10)(8)] / 0.10 = 120.","w":["100 is the price when D = 4.","80 equals E / k with r = k.","","64 belongs to the r = 8% case."],"g":1},{"u":"Unit IV","t":"Walter's Model","n":2073,"q":"One assumption of Walter's model is that","o":["the firm issues new equity every year","all financing is done through retained earnings","the firm uses heavy debt","the cost of capital keeps changing"],"a":1,"e":"No outside finance is used in Walter's model.","w":["No new equity is assumed.","","Walter assumes no external debt.","r and k are assumed constant."],"g":1},{"u":"Unit IV","t":"Gordon's Model","n":2074,"q":"Gordon's model is based on the","o":["irrelevance of dividends","operating cycle","bird-in-hand argument","tax shield on interest"],"a":2,"e":"Investors prefer certain dividends to uncertain future gains.","w":["Irrelevance is the Modigliani-Miller view.","The operating cycle is a working capital idea.","","The tax shield is about debt."],"g":1},{"u":"Unit IV","t":"Gordon's Model","n":2075,"q":"Gordon's model requires that the cost of equity (k) be","o":["equal to the dividend per share","equal to zero always","greater than the growth rate (g)","smaller than the growth rate (g)"],"a":2,"e":"If k is not above g the formula gives no sensible value.","w":["k and dividend are different things.","Zero cost is impossible.","","That makes the price infinite or negative."],"g":1},{"u":"Unit IV","t":"Gordon's Model","n":2076,"q":"With E = Rs 10, retention 50%, r = 15% and k = 12%, Gordon's share price is about","o":["Rs 111.11","Rs 83.33","Rs 100","Rs 62.50"],"a":0,"e":"g = 7.5%; P0 = 10 x 0.5 / (0.12 - 0.075) = 111.11.","w":["","83.33 is the price with zero retention.","100 has no basis.","62.50 divides by the wrong denominator."],"g":1},{"u":"Unit IV","t":"Gordon's Model","n":2077,"q":"Both Walter's and Gordon's models argue that dividend policy is","o":["irrelevant to the value of the firm","relevant to the value of the firm","illegal in India","meaningful only for debt"],"a":1,"e":"They belong to the relevance school.","w":["Irrelevance is the MM theory.","","Dividend policy is legal.","The models concern equity value."],"g":1},{"u":"Unit IV","t":"Gordon's Model","n":2078,"q":"Modigliani and Miller argue that in a perfect market dividend policy is","o":["the same as capital budgeting","decided by the government","the most important factor","irrelevant to firm value"],"a":3,"e":"Value depends only on earning power and investment policy.","w":["They are different decisions.","The government does not decide it.","That is the relevance view.",""],"g":1},{"u":"Unit IV","t":"Working Capital","n":2079,"q":"Gross working capital means","o":["current assets minus current liabilities","total investment in current assets","owner's capital only","fixed assets minus debt"],"a":1,"e":"Gross = total current assets.","w":["That is net working capital.","","Owner's capital is not the definition.","That is not a working capital measure."],"g":1},{"u":"Unit IV","t":"Working Capital","n":2080,"q":"Net working capital is","o":["equity minus debt","total current assets","fixed assets minus current assets","current assets minus current liabilities"],"a":3,"e":"NWC = CA - CL.","w":["That is a capital structure measure.","That is gross working capital.","That mixes unrelated items.",""],"g":1},{"u":"Unit IV","t":"Working Capital","n":2081,"q":"The minimum level of current assets needed at all times is","o":["permanent working capital","gross fixed capital","negative working capital","temporary working capital"],"a":0,"e":"Permanent working capital is always required.","w":["","Fixed capital is a different concept.","Negative means liabilities exceed assets.","Temporary is the extra seasonal need."],"g":1},{"u":"Unit IV","t":"Working Capital","n":2082,"q":"Extra stock bought for the festival season is financed by","o":["permanent working capital","temporary working capital","retained earnings only","share capital only"],"a":1,"e":"Seasonal needs are temporary working capital.","w":["Permanent is the stable minimum.","","Retained earnings suit the permanent part.","Seasonal needs are usually financed short-term."],"g":1},{"u":"Unit IV","t":"Working Capital","n":2083,"q":"Negative working capital means","o":["no current assets exist","fixed assets are negative","current assets exceed current liabilities","current liabilities exceed current assets"],"a":3,"e":"It signals a liquidity danger.","w":["The firm still has some current assets.","Fixed assets cannot be negative.","That is positive working capital.",""],"g":1},{"u":"Unit IV","t":"Operating Cycle","n":2084,"q":"The operating cycle is the time from","o":["starting the business to closing it","ordering fixed assets to using them","buying raw materials to collecting cash from customers","paying tax to filing returns"],"a":2,"e":"It tracks cash tied up in operations.","w":["That is the life of the business.","That is a capital budgeting period.","","That is a tax matter."],"g":1},{"u":"Unit IV","t":"Operating Cycle","n":2085,"q":"Raw material 30 days, WIP 15 days, finished goods 10 days, debtors 40 days: the gross operating cycle is","o":["35 days","60 days","65 days","95 days"],"a":3,"e":"30 + 15 + 10 + 40 = 95 days.","w":["35 is the creditors period used in the net cycle.","60 is the net cycle after deducting creditors.","65 leaves out debtors.",""],"g":1},{"u":"Unit IV","t":"Operating Cycle","n":2086,"q":"With a gross cycle of 95 days and creditors' period of 35 days, the net operating (cash) cycle is","o":["35 days","130 days","95 days","60 days"],"a":3,"e":"95 - 35 = 60 days.","w":["35 is only the creditors' period.","130 adds instead of subtracting.","95 ignores the credit from suppliers.",""],"g":1},{"u":"Unit IV","t":"Operating Cycle","n":2087,"q":"A shorter operating cycle generally means","o":["more working capital is needed","less working capital is needed","higher fixed assets","no working capital is needed"],"a":1,"e":"Funds return to cash faster.","w":["A longer cycle needs more.","","Fixed assets are unrelated.","Some working capital is always needed."],"g":1},{"u":"Unit IV","t":"Working Capital Determinants","n":2088,"q":"Which business generally needs more working capital?","o":["A consultant working alone","A manufacturing firm","A small service firm","A bank counter-service business with no stock"],"a":1,"e":"Manufacturers hold raw material, WIP and finished stock.","w":["A lone consultant needs little.","","Services hold little stock.","No stock means low need."],"g":1},{"u":"Unit IV","t":"Working Capital Determinants","n":2089,"q":"Giving liberal credit to customers will","o":["reduce receivables","increase the working capital requirement","decrease the working capital requirement","have no effect"],"a":1,"e":"More credit means more money locked in debtors.","w":["It increases receivables.","","It raises, not lowers, the need.","Credit policy clearly matters."],"g":1},{"u":"Unit IV","t":"Working Capital Determinants","n":2090,"q":"A seasonal business needs more of","o":["bonus shares","preference capital","permanent fixed capital","temporary working capital"],"a":3,"e":"Seasonal peaks create temporary needs.","w":["Bonus shares bring no funds.","Preference capital is long-term.","Fixed capital does not vary with season.",""],"g":1}]);
